(5, 3, '1.3 Meta Ads dashboard', 'Spend, reach, impressions, leads/conversions, dan performa\ncampaign dapat dipantau dari sistem.', 'manual', NULL, NULL, 0.00, 1.00, 'angka', NULL, 1, 3, 1, '2026-07-28 10:20:01', '2026-08-03 09:43:24', NULL),
(6, 3, '1.4 Native Kanban Insight Untuk setiap Karyawan dan KPI', 'Board, list, card, assignee, deadline, status, komentar, dan riwayat\nperubahan tersedia di sistem internal.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 4, 1, '2026-07-28 10:20:08', '2026-08-01 04:37:07', NULL),
(7, 3, '1.5 Invoice maker + sales pipeline', 'Invoice dapat dibuat dari data deal/customer dan statusnya\nterhubung ke pipeline serta pembukuan.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 5, 1, '2026-07-28 10:20:16', '2026-08-01 04:37:17', NULL),
(8, 3, '1.6 Pembukuan perusahaan', 'Pemasukan, pengeluaran, anggaran, kategori, entitas perusahaan,\ndan keterangan transaksi tercatat serta dapat dilaporkan.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 6, 1, '2026-07-28 10:20:24', '2026-08-01 04:37:27', NULL),
(10, 3, '1.7 Omnichannel Chat Insight', 'Chat masuk dapat dipantau, dikelompokkan, diberi status,\ndianalisis, dan dibalas dari dashboard.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 8, 1, '2026-07-28 10:20:37', '2026-08-01 04:37:38', NULL),
(11, 4, '2.1 Marketing Bootcamp  pre-recorded', 'Kurikulum, recording, worksheet, assessment,\nonboarding, dan sales asset siap dijual evergreen.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 1, 1, '2026-07-28 10:25:50', '2026-08-01 05:42:57', NULL),
(12, 4, '2.2 Marketing Bootcamp - live session', 'Format cohort, jadwal, learning outcome,\nassignment, mentoring, dan feedback loop siap\ndijalankan.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 2, 1, '2026-07-28 10:26:08', '2026-08-01 05:43:01', NULL),
(13, 4, '2.3 Update Academy + re-recording', 'Audit modul, revisi materi, recording ulang, upload\nLMS, dan QA selesai.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 3, 1, '2026-07-28 10:26:20', '2026-08-01 05:43:08', NULL),
(14, 4, '2.4 Coaching dan workshop offline', 'Offer, modul fasilitator, deck, worksheet, pricing,\nvenue checklist, dan follow-up system tersedia.', 'manual', NULL, NULL, 0.00, 1.00, 'angka', NULL, 1, 4, 1, '2026-07-28 10:26:32', '2026-08-03 09:43:42', NULL),
(15, 4, '2.5 Software house launch  September', 'Offer, service scope, portfolio/case study, proposal,\nsales pipeline, delivery SOP, dan pilot client siap.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 5, 1, '2026-07-28 10:26:43', '2026-08-01 05:43:19', NULL),
(16, 4, '2.6 Endorsement + sponsorship', 'Media kit, package, pricing guardrail, prospect list,\noutreach pipeline, dan delivery checklist tersedia.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 6, 1, '2026-07-28 10:26:54', '2026-08-01 05:43:23', NULL),
(17, 4, '2.7 Value ladder + pricing', 'Dua ladder B2C/B2B, offer per level, upgrade path,\nmargin, dan pricing hypothesis tersedia.', 'manual', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 7, 1, '2026-07-28 10:27:05', '2026-08-01 05:43:29', NULL),
(18, 5, '3.1 Instagram mencapai 75.000 followers', 'Meningkatkan audience personal brand Freddie Kashawan di Instagram hingga 175.000 followers pada akhir Q3 2026.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 9, 1, 1, '2026-07-31 07:17:24', '2026-08-01 05:42:32', NULL),
(19, 5, '3.2 TikTok mencapai 75.000 followers', 'Meningkatkan audience personal brand Freddie Kashawan di TikTok hingga 75.000 followers pada akhir Q3 2026.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 9, 2, 1, '2026-07-31 07:18:32', '2026-08-01 05:42:37', NULL),
(20, 5, '3.3 YouTube mencapai 30.000 subscribers', 'Meningkatkan audience personal brand Freddie Kashawan di YouTube hingga 50.000 subscribers pada akhir Q3 2026.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 9, 3, 1, '2026-07-31 07:18:58', '2026-08-01 05:42:42', NULL),
(21, 5, '3.4 WhatsApp Channel mencapai 10.000 followers', 'Meningkatkan audience WhatsApp Channel Freddie Kashawan hingga 10.000 followers pada akhir Q3 2026.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 9, 4, 1, '2026-07-31 07:19:06', '2026-08-01 05:42:47', NULL),
(22, 7, '5.1 Finalisasi blueprint produk, arsitektur, dan user flow LMS', '100% alur register, login, pembelian, belajar, live class, community, certificate, dan admin dashboard disetujui; 0 kebutuhan kritis yang belum diputuskan', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 1, 1, '2026-07-31 07:27:18', '2026-08-01 05:21:32', NULL),
(23, 7, '5.2 Core LMS self-hosted siap digunakan di production', '100% fitur utama berjalan di domain dan server sendiri; login, role access, course, lesson, video, resource, dan progress aktif; uptime minimal 99,5%; loading halaman utama di bawah 3 detik', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 2, 1, '2026-07-31 07:29:15', '2026-08-01 05:21:40', NULL),
(24, 7, '5.3 Tiga learning track AI tersedia di dalam LMS', 'Minimal 3 track: AI for Marketing, AI for Business, serta AI for Content & Filmmaking; minimal 1 flagship course per track dan total minimal 30 lesson siap dipelajari', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 3, 1, '2026-07-31 07:30:21', '2026-08-01 05:21:47', NULL),
(25, 7, '5.4 Payment gateway dan automated enrollment berjalan end-to-end', 'Pembayaran sekali bayar dan subscription/cicilan aktif; minimal QRIS, virtual account, e-wallet, dan kartu; keberhasilan transaksi minimal 95%; akses kelas otomatis diberikan maksimal 1 menit setelah pembayaran', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 4, 1, '2026-07-31 07:30:47', '2026-08-01 05:22:12', NULL),
(26, 7, '5.5 Sistem live class dan event management aktif', 'Kalender event, RSVP, reminder, Zoom/live stream, attendance, serta replay aktif; minimal 3 sesi pilot berhasil; minimal 95% peserta berhasil bergabung; replay tersedia maksimal 24 jam setelah sesi', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 5, 1, '2026-07-31 07:31:15', '2026-08-01 05:22:17', NULL),
(27, 7, '5.6 Community chat dan integrasi WhatsApp aktif', '100% course memiliki ruang komunitas; tersedia channel, thread, mention, direct message, file sharing, dan moderation; WhatsApp reminder serta customer support aktif; delivery rate notifikasi minimal 95%', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 6, 1, '2026-07-31 07:31:31', '2026-08-01 05:22:22', NULL),
(28, 7, '5.7 Progress tracking, assessment, certificate, dan gamification aktif Persentase akurasi fi', '100% progress lesson tersimpan; setiap course memiliki quiz atau project; sertifikat otomatis diterbitkan kepada 100% peserta yang memenuhi syarat; tersedia point, badge, atau level untuk mendorong engagement', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 7, 1, '2026-07-31 07:31:49', '2026-08-01 05:22:32', NULL),
(29, 7, '5.8 Admin dashboard dan learning analytics tersedia', 'Dashboard menampilkan minimal 8 metrik: revenue, transaksi, enrollment, active learner, progress, completion, live attendance, dan community engagement; data transaksi tercatat otomatis dan dapat diekspor', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 8, 1, '2026-07-31 07:32:04', '2026-08-01 05:22:38', NULL),
(30, 7, '5.9 Beta testing dan public launch LMS berhasil dilakukan', 'Minimal 50 beta tester; onboarding completion minimal 80%; CSAT minimal 4,3/5; 0 bug critical saat launching; backup dan restore berhasil diuji; LMS resmi dibuka untuk publik', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 9, 1, '2026-07-31 07:32:19', '2026-08-01 05:22:43', NULL),
(31, 7, '5.10 Sistem multi-program dan landing page berjalan', 'Admin dapat membuat dan menjual minimal 5 tipe program—course, membership, cohort, workshop, dan event—beserta landing page masing-masing tanpa coding.', 'kartu', 'todo', NULL, 0.00, NULL, 'angka', '{\"name\":\"Penting\",\"color\":\"bg-amber-500\"}', 14, 10, 1, '2026-07-31 07:42:18', '2026-08-01 05:22:47', NULL),
(32, 7, '5.11 Backend dan UX siap untuk mobile app iOS dan Android', 'API backend, authentication, progress sync, event, community, notification structure, dan responsive mobile experience siap menjadi fondasi aplikasi App Store dan Google Play.', 'kartu', 'todo', NULL, 0.00, NULL, 'angka', '{\"name\":\"Penting\",\"color\":\"bg-amber-500\"}', 14, 11, 1, '2026-07-31 07:42:33', '2026-08-01 05:22:52', NULL),
(33, 6, '4.1 Finalisasi learning track dan kurikulum AI Preneur', 'Menyusun kurikulum lengkap untuk setiap program, mulai dari hasil pembelajaran, modul, materi praktik, tugas, hingga standar kelulusan peserta.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 1, 1, '2026-07-31 08:09:03', '2026-08-01 05:23:02', NULL),
(34, 6, '4.2 Produksi Academy pre-recorded', 'Menyelesaikan produksi materi pembelajaran pre-recorded yang dapat digunakan sebagai produk Academy AI Preneur.\n\nTarget minimum:\n\nMinimal 1 program utama per learning track.\nMinimal 10 lesson per program.\nTotal minimal 30 video pembelajaran.\nSetiap lesson memiliki materi pendukung.\nSetiap program memiliki tugas praktik.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 2, 1, '2026-07-31 08:09:39', '2026-08-01 05:23:07', NULL),
(35, 6, '4.3 Menjalankan Bootcamp live pertama', 'Menjalankan satu batch Bootcamp AI Preneur secara live dengan jadwal, mentor, materi, tugas, dan pendampingan yang terstruktur.\n\nTarget minimum:\n\nMinimal 30 peserta.\nKehadiran rata-rata minimal 80%.\nSeluruh sesi berjalan sesuai jadwal.\nSeluruh materi dan tugas tersampaikan.\nMinimal 80% peserta menyelesaikan program.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 3, 1, '2026-07-31 08:10:02', '2026-08-01 05:41:07', NULL),
(36, 6, '4.4 Finalisasi mentor, instructor, dan guest speaker', 'Menentukan pengajar utama, mentor pendamping, serta guest speaker yang sesuai dengan setiap topik pembelajaran.\n\nOutput:\n\nInstructor utama setiap program.\nMentor pendamping peserta.\nGuest speaker sesuai kebutuhan.\nPembagian topik dan jadwal mengajar.\nBrief dan standar penyampaian materi.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 4, 1, '2026-07-31 08:10:24', '2026-08-01 05:41:17', NULL),
(37, 6, '4.5 Menyelesaikan learning materials dan participant kit', 'Menyiapkan seluruh materi pendukung agar peserta tidak hanya menonton atau mengikuti kelas, tetapi langsung mempraktikkan materi yang diajarkan.\n\nMateri pendukung:\n\nWorkbook.\nPrompt library.\nTemplate siap pakai.\nChecklist.\nStudi kasus.\nAssignment.\nFinal project.\nRekap materi setiap sesi.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 5, 1, '2026-07-31 08:10:49', '2026-08-01 05:41:21', NULL),
(38, 6, '4.6 Mencapai kepuasan dan hasil belajar peserta', 'Memastikan program memberikan pengalaman belajar yang berkualitas dan membantu peserta menghasilkan implementasi nyata.\n\nTarget pendukung:\n\nCompletion rate minimal 80%.\nKehadiran rata-rata minimal 80%.\nMinimal 70% peserta menyelesaikan final project.\nMinimal 70% peserta menyatakan materi dapat langsung dipraktikkan.\nNilai mentor dan materi minimal 4,3 dari 5.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 6, 1, '2026-07-31 08:13:11', '2026-08-01 05:41:25', NULL),
(39, 6, '4.7 Menjalankan campaign peluncuran Bootcamp dan Academy', 'Membuat dan menjalankan campaign pemasaran untuk memperkenalkan program, mengumpulkan leads, dan menghasilkan peserta berbayar.\n\nAktivitas utama:\n\nContent campaign.\nWebinar atau free class.\nLanding page campaign.\nWhatsApp follow-up.\nEmail campaign.\nAffiliate dan partnership.\nRetargeting calon peserta.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 7, 1, '2026-07-31 08:13:35', '2026-08-01 05:41:29', NULL),
(40, 6, '4.8 Mencapai validasi penjualan program', 'Menguji daya tarik produk dan membuktikan bahwa program Bootcamp serta Academy memiliki permintaan pasar yang nyata.\n\nTarget pendukung:\n\nMinimal 100 total peserta berbayar.\nConversion rate leads ke pembelian minimal 5%.\nRefund maksimal 5%.\nMinimal satu program mencapai break-even.\nSeluruh transaksi dan peserta terdokumentasi.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 8, 1, '2026-07-31 08:13:56', '2026-08-01 05:41:41', NULL),
(41, 6, '4.9 Menghasilkan testimonial dan success story peserta', 'Mengumpulkan bukti hasil peserta sebagai aset pemasaran dan validasi kualitas program.\n\nTarget minimum:\n\nMinimal 20 testimonial tertulis.\nMinimal 10 video testimonial.\nMinimal 5 studi kasus implementasi.\nMinimal 3 success story dengan hasil terukur.\nIzin penggunaan testimonial untuk marketing.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 9, 1, '2026-07-31 08:14:21', '2026-08-01 05:41:46', NULL),
(42, 6, '4.10 Menyusun sistem operasional program yang dapat direplikasi', 'Membuat SOP agar pelaksanaan Bootcamp dan Academy berikutnya tidak selalu dibangun ulang dari awal.\n\nSOP yang dibuat:\n\nPersiapan program.\nOnboarding peserta.\nPengelolaan instructor.\nPelaksanaan kelas.\nPengumpulan tugas.\nPendampingan peserta.\nPenanganan kendala.\nEvaluasi dan feedback.\nPengumpulan testimonial.\nPelaksanaan batch berikutnya.', 'kartu', NULL, NULL, 0.00, NULL, 'angka', NULL, 1, 10, 1, '2026-07-31 08:14:44', '2026-08-01 05:42:15', NULL),
(43, 8, 'Membangun jaringan affiliate aktif sebanyak 1.500.', NULL, 'manual', NULL, NULL, 1500.00, 117.00, 'angka', NULL, 19, 3, 1, '2026-07-31 09:12:44', '2026-07-31 09:15:28', '2026-07-31 09:15:28'),
