INSERT INTO `objectives` (`id`, `year`, `quarter`, `title`, `description`, `priority`, `omset_target`, `omset_owner_id`, `position`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(3, 2026, 3, 'Sistem AI Preneur terautomasi', 'Satu operating system untuk konten, ads, pekerjaan, keuangan, pembelajaran, dan komunikasi.', NULL, NULL, NULL, 2, 1, '2026-07-28 09:51:54', '2026-08-01 04:15:05', NULL),
(4, 2026, 3, 'Pengembangan bisnis AI Preneur ( ACADEMY CURICULUM)', 'Produk edukasi, software house, partnership, dan value ladder B2C/B2B yang scalable.', NULL, NULL, NULL, 3, 1, '2026-07-28 09:52:56', '2026-08-01 05:14:06', NULL),
(5, 2026, 3, 'Audience Growth FK (FOLLOWERS SUBSCRIBER)', 'Pertumbuhan personal brand FK lintas Instagram, TikTok, YouTube, WhatsApp Channel, dan Instagram\nChannel.', NULL, NULL, NULL, 4, 1, '2026-07-28 09:53:12', '2026-08-01 05:15:16', NULL),
(6, 2026, 3, 'Bootcamp dan Academy AI Preneur Kurikulum', 'Mengembangkan dan menjalankan program Bootcamp dan Academy AI Preneur yang terstruktur, relevan dengan kebutuhan pasar, memberikan hasil nyata bagi peserta, serta dapat dikembangkan menjadi produk edukasi yang scalable.', NULL, NULL, NULL, 5, 1, '2026-07-28 11:26:35', '2026-08-01 08:11:44', NULL),
(7, 2026, 3, 'LMS AI Preneur x FK Sudah Ready', 'Membangun platform pembelajaran AI milik AI Preneur di domain dan server sendiri yang mengintegrasikan course, pembayaran, live class, komunitas, WhatsApp, progress learning, dan dashboard bisnis dalam satu ekosistem yang scalable.', NULL, NULL, NULL, 6, 1, '2026-07-31 04:13:01', '2026-08-01 08:11:26', NULL),
(8, 2026, 3, 'Mencapai Target Omzet E-Commerce dan Distributor', 'Fokus strategi pemasaran CMO AI untuk mendorong omzet e-commerce Rp500.000.000/bulan dan membangun jaringan distributor & affiliate aktif.', '{\"name\":\"CMO AI\",\"color\":\"bg-indigo-600\"}', 500000000.00, 19, 1, 1, '2026-07-31 09:12:44', '2026-07-31 09:15:28', '2026-07-31 09:15:28'),
(9, 2026, 3, 'Meningkatkan Penjualan E-Commerce dan Distributor', 'Fokus untuk memastikan margin dan cashflow yang sehat sambil mencapai target omzet.\nAlasan dipilih: Menjaga keseimbangan antara penjualan e-commerce dan produksi agar tidak merusak cashflow.', '{\"name\":\"CFO AI\",\"color\":\"bg-blue-600\"}', 500000000.00, 17, 2, 1, '2026-07-31 09:12:44', '2026-07-31 09:15:37', '2026-07-31 09:15:37'),
(10, 2026, 3, 'Meningkatkan Omzet E-Commerce SKINKU', 'SKINKU berfokus pada peningkatan omzet e-commerce dan distributor serta pengembangan jaringan affiliate di Q3 2026. Target omzet e-commerce sebesar Rp500.000.000 per bulan memerlukan evaluasi dari komposisi SKU existing, kontribusi Perfume dan Acne Series, serta peluncuran produk baru. Selain itu, untuk mencapai 30 distributor aktif dengan total omzet Rp9.000.000.000 per kuartal, relasi dan dukungan pada distributor sangat penting. Jaringan affiliate 5.000 orang harus diperoleh dengan memperhatikan produktivitas dan retensi serta keterlibatan aktif dari affiliator. Kesiapan produk juga perlu diperhatikan, terutama dengan tingginya permintaan terhadap produk yang sudah terbukti laku.\nAlasan dipilih: Kenaikan omzet e-commerce secara signifikan akan mendongkrak cashflow dan meningkatkan margin dalam jangka panjang.', '{\"name\":\"COO AI\",\"color\":\"bg-sky-600\"}', 500000000.00, 15, 3, 1, '2026-07-31 09:12:44', '2026-07-31 09:15:44', '2026-07-31 09:15:44'),
(11, 2026, 3, 'Target Omzet Penjualan FK (Fashion & Konsumen)', 'Fokus pencapaian omzet lini produk FK Q3 2026 melalui kanal distribusi & penjualan langsung.', '{\"name\":\"FK\",\"color\":\"bg-emerald-600\"}', 300000000.00, 16, 4, 1, '2026-07-31 09:12:44', '2026-07-31 09:28:27', '2026-07-31 09:28:27'),
(12, 2026, 3, 'Target Omzet Ekosistem Aipreneur Portal', 'Peningkatan omzet berlangganan & lisensi portal ekosistem Aipreneur di Q3 2026.', '{\"name\":\"AIPRENEUR\",\"color\":\"bg-indigo-600\"}', 750000000.00, 17, 5, 1, '2026-07-31 09:12:44', '2026-07-31 09:28:41', '2026-07-31 09:28:41'),
(13, 2026, 3, 'Parameter Omzet 1 M', NULL, NULL, 1000000000.00, 1, 7, 1, '2026-08-01 04:12:56', '2026-08-01 08:11:14', NULL);
